import React, { useEffect, useState } from "react";
import { useCart } from "./GioHang/CartContext";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min.js";

import "./CSS/HomePage.css";

const HomePage = () => {
    const { addToCart } = useCart();

    const [priceFrom, setPriceFrom] = useState("");
    const [priceTo, setPriceTo] = useState("");
    const [selectedCategories, setSelectedCategories] = useState([]);
    const [searchTerm, setSearchTerm] = useState("");
    const [filteredProducts, setFilteredProducts] = useState([]);

    const allProducts = [
        { id: 1, name: "Sản phẩm 1", price: 250000, category: "Đồ nam", image: "/assets/product1.jpg" },
        { id: 2, name: "Sản phẩm 2", price: 300000, category: "Đồ nữ", image: "/assets/product2.jpg" },
        { id: 3, name: "Sản phẩm 3", price: 200000, category: "Đồ nam", image: "/assets/product3.jpg" },
        { id: 4, name: "Sản phẩm 4", price: 400000, category: "Trẻ em", image: "/assets/product4.jpg" },
        { id: 5, name: "Sản phẩm 5", price: 350000, category: "Đồ nữ", image: "/assets/product5.jpg" }
    ];

    const handleCategoryChange = (category) => {
        setSelectedCategories((prev) =>
            prev.includes(category)
                ? prev.filter((c) => c !== category)
                : [...prev, category]
        );
    };

    const applyFilters = () => {
        let filtered = allProducts;

        // Lọc theo giá
        if (priceFrom) {
            filtered = filtered.filter((p) => p.price >= parseInt(priceFrom));
        }
        if (priceTo) {
            filtered = filtered.filter((p) => p.price <= parseInt(priceTo));
        }

        // Lọc theo danh mục
        if (selectedCategories.length > 0) {
            filtered = filtered.filter((p) => selectedCategories.includes(p.category));
        }

        // Lọc theo tên
        if (searchTerm.trim() !== "") {
            filtered = filtered.filter((p) =>
                p.name.toLowerCase().includes(searchTerm.toLowerCase())
            );
        }

        setFilteredProducts(filtered);
    };

    useEffect(() => {
        setFilteredProducts(allProducts);
    }, []);

    useEffect(() => {
        applyFilters();
    }, [priceFrom, priceTo, selectedCategories, searchTerm]);

    return (
        <div className="container mb-4 mt-4">
            {/* Bộ lọc */}
            <div className="row justify-content-center">
                <div className="col-md-3 mb-4">
                    <div className="border rounded p-3 bg-light shadow-sm">
                        <h5>Tìm theo tên</h5>
                        <input
                            type="text"
                            className="form-control mb-3"
                            placeholder="Nhập tên sản phẩm..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />

                        <h5>Chọn khoảng giá</h5>
                        <input
                            type="number"
                            className="form-control mb-2"
                            placeholder="Từ"
                            value={priceFrom}
                            onChange={(e) => setPriceFrom(e.target.value)}
                        />
                        <input
                            type="number"
                            className="form-control mb-2"
                            placeholder="Đến"
                            value={priceTo}
                            onChange={(e) => setPriceTo(e.target.value)}
                        />

                        <h5 className="mt-3">Chọn danh mục</h5>
                        {["Đồ nam", "Đồ nữ", "Trẻ em"].map((cat, index) => (
                            <div className="form-check" key={index}>
                                <input
                                    className="form-check-input"
                                    type="checkbox"
                                    id={`cat-${index}`}
                                    checked={selectedCategories.includes(cat)}
                                    onChange={() => handleCategoryChange(cat)}
                                />
                                <label className="form-check-label" htmlFor={`cat-${index}`}>{cat}</label>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Danh sách sản phẩm */}
                <div className="col-md-9">
                    <h4 className="mb-4 text-primary">Có {filteredProducts.length} sản phẩm được tìm thấy</h4>
                    <div className="row">
                        {filteredProducts.map((product) => (
                            <div key={product.id} className="col-md-4 mb-4">
                                <div className="card h-100 shadow-sm hover-shadow">
                                    <img
                                        src={product.image}
                                        className="card-img-top"
                                        alt={product.name}
                                        style={{ height: "200px", objectFit: "cover" }}
                                    />
                                    <div className="card-body text-center">
                                        <h5 className="card-title">{product.name}</h5>
                                        <p className="card-text text-primary fw-bold">
                                            {product.price.toLocaleString()}₫
                                        </p>
                                        <button
                                            className="btn btn-success w-100 rounded-pill shadow-sm"
                                            onClick={() => addToCart(product)}
                                        >
                                            Thêm vào giỏ hàng
                                        </button>
                                    </div>
                                </div>
                            </div>
                        ))}
                        {filteredProducts.length === 0 && (
                            <div className="text-center text-muted">Không tìm thấy sản phẩm phù hợp</div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default HomePage;
